import { expect, test } from "bun:test"
import { shouldHandlePasteAsAttachment } from "./interaction"

test("handles clipboard files, and native images only when the clipboard has no text", () => {
  expect(shouldHandlePasteAsAttachment(clipboard(), false)).toBe(false)
  expect(shouldHandlePasteAsAttachment(clipboard(), true)).toBe(true)
  expect(shouldHandlePasteAsAttachment(clipboard(["text/plain"]), true)).toBe(false)
  expect(shouldHandlePasteAsAttachment(clipboard([], [{ kind: "file" }]), false)).toBe(true)
})

function clipboard(types: string[] = [], items: Array<{ kind: string }> = []) {
  return { types, items } as unknown as DataTransfer
}

import { describe, expect, test } from "bun:test"
import { createStore } from "solid-js/store"
import { Skill } from "@opencode/schema/skill"
import type { ComposerPersistedState } from "../types"
import { createComposerEditorActions } from "./actions"

const context = { key: "file:src/index.ts", type: "file" as const, path: "src/index.ts" }

function createPromptStore() {
  return createComposerEditorActions(
    createStore<ComposerPersistedState>({
      prompt: [
        { type: "text", content: "old", start: 0, end: 3 },
        {
          type: "image",
          id: "attachment-1",
          filename: "notes.txt",
          mime: "text/plain",
          blob: { id: "a", url: "blob:a" },
        },
      ],
      cursor: 3,
      model: { providerID: "anthropic", modelID: "claude-sonnet", variant: null },
      context: { items: [context] },
    }),
  )
}

describe("Composer store", () => {
  test("updates prompt text and cursor together while preserving attachments", () => {
    const prompt = createPromptStore()

    prompt.setText("updated")

    expect(prompt.state.prompt).toEqual([
      { type: "text", content: "updated", start: 0, end: 7 },
      {
        type: "image",
        id: "attachment-1",
        filename: "notes.txt",
        mime: "text/plain",
        blob: { id: "a", url: "blob:a" },
      },
    ])
    expect(prompt.state.cursor).toBe(7)
  })

  test("inserts text without flattening structured mentions", () => {
    const [state, setState] = createStore<ComposerPersistedState>({
      prompt: [
        { type: "text", content: "A ", start: 0, end: 2 },
        { type: "file", path: "one", content: "@one", start: 2, end: 6 },
        { type: "text", content: " B", start: 6, end: 8 },
      ],
      cursor: 2,
      context: { items: [] },
    })

    const prompt = createComposerEditorActions([state, setState])

    prompt.addText("X\nY")

    expect(prompt.state.prompt).toEqual([
      { type: "text", content: "A X\nY", start: 0, end: 5 },
      { type: "file", path: "one", content: "@one", start: 5, end: 9 },
      { type: "text", content: " B", start: 9, end: 11 },
    ])
    expect(prompt.state.cursor).toBe(5)
  })

  test("mutates mentions, attachments, and context through editor actions", () => {
    const prompt = createPromptStore()

    prompt.addMention({ type: "file", path: "src/app.ts", content: "@src/app.ts", start: 0, end: 0 })
    prompt.removeAttachment("attachment-1")
    prompt.removeContext(context.key)

    expect(prompt.state.context.items).toEqual([])
    expect(prompt.state.prompt).toEqual([
      { type: "text", content: "old", start: 0, end: 3 },
      { type: "file", path: "src/app.ts", content: "@src/app.ts", start: 3, end: 14 },
      { type: "text", content: " ", start: 14, end: 15 },
    ])
  })

  test("prepends a skill mention to an attachment-only draft without flattening it", () => {
    const prompt = createPromptStore()
    prompt.setPrompt([{ type: "file", path: "one", content: "@one", start: 0, end: 4 }], 4)
    prompt.addMention(
      {
        type: "skill",
        id: Skill.ID.make("show-me"),
        name: Skill.Name.make("Show Me"),
        content: "@show-me",
        start: 0,
        end: 0,
      },
      { start: 0, end: 0 },
    )
    expect(prompt.state.prompt).toMatchObject([
      { type: "skill", id: "show-me", content: "@show-me", start: 0, end: 8 },
      { type: "text", content: " ", start: 8, end: 9 },
      { type: "file", path: "one", content: "@one", start: 9, end: 13 },
    ])
    expect(prompt.state.cursor).toBe(9)
  })
})

import { expect, test } from "bun:test"
import { createRoot } from "solid-js"
import { createStore } from "solid-js/store"
import { createComposerEditor } from "../src/composer/editor/interaction"
import type { ComposerPersistedState } from "../src/composer/types"

test("a disconnected composer preserves text and ignores submissions until reconnect", () => {
  createRoot((dispose) => {
    const [state, setState] = createStore({ connected: false, submissions: 0 })

    const store = createStore<ComposerPersistedState>({
      prompt: [{ type: "text", content: "keep my draft", start: 0, end: 13 }],
      context: { items: [] },
    })

    const editor = createComposerEditor({
      store,
      commands: () => [],
      context: () => [],
      searchContextFiles: () => [],
      view: {
        submit: {
          available: () => state.connected,
          stopping: () => false,
          onStop() {},
          onSubmit: () => setState("submissions", (count) => count + 1),
        },
      },
    })

    expect(editor.canSubmit()).toBe(false)
    editor.submit()
    expect(state.submissions).toBe(0)
    expect(editor.value()).toBe("keep my draft")
    setState("connected", true)
    expect(editor.canSubmit()).toBe(true)
    editor.submit()
    expect(state.submissions).toBe(1)
    dispose()
  })
})

import { expect, test } from "bun:test"
import { createComputed, createRoot } from "solid-js"
import { SessionMessage } from "@opencode/schema/session-message"
import { ServerScope } from "@/runtime/server/scope"
import { createComposerState, type ComposerStore } from "@/composer/state"
import { createComposerEditorActions } from "@/composer/editor/actions"
import { flushPersisted } from "@/runtime/persistence/persist"

function setup(read: () => string | null | Promise<string | null> = () => null) {
  return createRoot((dispose) => {
    const writes: ComposerStore[] = []

    const state = createComposerState(ServerScope.local, { draftID: "composer-write-batch-test" }, undefined, {
      platform: "desktop",
      os: "windows",
      windowID: "composer-write-batch-test",
      openExternal() {},
      restart: async () => {},
      notify: async () => {},
      storage: () => ({
        getItem: read,
        setItem: (_key, value) => {
          writes.push(JSON.parse(value))
        },
        removeItem() {},
      }),
    })

    return { state, writes, editor: createComposerEditorActions(state.store), dispose }
  })
}

test("composer-write-batch: a burst of edits persists once with prompt, cursor and retry together", async () => {
  const value = setup()

  try {
    await value.state.ready.promise
    value.state.context.add({ type: "file", path: "src/queue.ts", preview: "await queue.flush()" })
    value.state.retry.set({ id: SessionMessage.ID.create(), agent: "build", providerID: "test", modelID: "test" })
    flushPersisted()
    value.writes.length = 0
    value.editor.setPrompt([{ type: "text", content: "keep ordering", start: 0, end: 13 }], 13)
    value.editor.setCursor(12)
    expect(value.writes).toHaveLength(0)
    flushPersisted()
    expect(value.writes).toHaveLength(1)
    expect(value.writes[0]).toMatchObject({
      prompt: [{ type: "text", content: "keep ordering", start: 0, end: 13 }],
      cursor: 12,
      context: { items: [{ path: "src/queue.ts", preview: "await queue.flush()" }] },
    })
    expect(value.writes[0].retry).toBeUndefined()
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: a save with no serialized change writes nothing", async () => {
  const value = setup()

  try {
    await value.state.ready.promise
    value.state.set([{ type: "text", content: "previous", start: 0, end: 8 }], 5)
    value.state.mode.set("shell")
    flushPersisted()
    value.writes.length = 0
    value.editor.setCursor(5)
    value.state.mode.set("shell")
    flushPersisted()
    expect(value.writes).toHaveLength(0)
    value.state.reset()
    flushPersisted()
    expect(value.writes).toHaveLength(1)
    expect(value.writes[0]).toMatchObject({ prompt: [{ content: "" }], cursor: 0, mode: "shell" })
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: state replacement snapshots the value at save time", async () => {
  const value = setup()

  try {
    await value.state.ready.promise
    value.state.set([{ type: "text", content: "previous", start: 0, end: 8 }], 5)
    flushPersisted()
    value.writes.length = 0
    const prompt = [{ type: "text" as const, content: "next", start: 0, end: 4 }]
    value.state.set(prompt)
    prompt[0].content = "changed outside the store"
    expect(value.state.current()[0]).toMatchObject({ content: "next" })
    flushPersisted()
    expect(value.writes).toHaveLength(1)
    expect(value.writes[0].prompt).toEqual([{ type: "text", content: "next", start: 0, end: 4 }])
    expect(value.writes[0].cursor).toBe(5)
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: the last edit in a window wins and attachments are retained", async () => {
  const value = setup()

  try {
    await value.state.ready.promise
    value.state.set(
      [
        { type: "text", content: "old", start: 0, end: 3 },
        {
          type: "image",
          id: "image",
          filename: "diagram.png",
          mime: "image/png",
          blob: { id: "diagram", url: "blob:diagram" },
        },
      ],
      3,
    )
    flushPersisted()
    value.writes.length = 0
    value.editor.setText("new")
    value.editor.addText(" notes")
    flushPersisted()
    expect(value.writes).toHaveLength(1)
    expect(value.writes[0].cursor).toBe(9)
    expect(value.writes[0].prompt).toEqual([
      { type: "text", content: "new notes", start: 0, end: 9 },
      {
        type: "image",
        id: "image",
        filename: "diagram.png",
        mime: "image/png",
        blob: { id: "diagram", url: "blob:diagram" },
      },
    ])
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: an edit still wins over a pending persisted read", async () => {
  const loading = Promise.withResolvers<string>()
  const value = setup(() => loading.promise)

  try {
    value.editor.setPrompt([{ type: "text", content: "new", start: 0, end: 3 }], 3)
    loading.resolve(
      JSON.stringify({
        prompt: [{ type: "text", content: "old", start: 0, end: 3 }],
        cursor: 1,
        context: { items: [] },
      }),
    )
    await value.state.ready.promise
    expect(value.state.current()).toEqual([{ type: "text", content: "new", start: 0, end: 3 }])
    expect(value.state.cursor()).toBe(3)
    flushPersisted()
    expect(value.writes).toHaveLength(1)
    expect(value.writes[0].prompt).toEqual([{ type: "text", content: "new", start: 0, end: 3 }])
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: observers see every edit before anything is persisted", async () => {
  const value = setup()

  try {
    await value.state.ready.promise
    createRoot((dispose) => {
      const observed: number[] = []
      createComputed(() => {
        value.state.current()
        observed.push(value.writes.length)
      })
      value.editor.setPrompt([{ type: "text", content: "new", start: 0, end: 3 }], 3)
      value.editor.setText("replace")
      value.editor.addText(" and insert")
      value.state.set([{ type: "text", content: "restore", start: 0, end: 7 }], 7)
      value.state.reset()
      expect(observed).toEqual([0, 0, 0, 0, 0, 0])
      flushPersisted()
      expect(value.writes).toHaveLength(1)
      dispose()
    })
  } finally {
    value.dispose()
  }
})

test("composer-write-batch: disposing the owner saves pending edits", async () => {
  const value = setup()
  await value.state.ready.promise
  value.editor.setPrompt([{ type: "text", content: "unsaved", start: 0, end: 7 }], 7)
  expect(value.writes).toHaveLength(0)
  value.dispose()
  expect(value.writes).toHaveLength(1)
  expect(value.writes[0].prompt).toEqual([{ type: "text", content: "unsaved", start: 0, end: 7 }])
})

import { describe, expect, test } from "bun:test"
import { createRoot } from "solid-js"
import { createStore } from "solid-js/store"
import { createComposerAttachments } from "@/composer/attachments/attachments"
import type { ComposerPrompt } from "@/composer/types"

function target() {
  const [store, setStore] = createStore<{ prompt: ComposerPrompt; cursor: number }>({
    prompt: [{ type: "text", content: "", start: 0, end: 0 }],
    cursor: 0,
  })

  return {
    prompt: store,
    capture: {
      current: () => store.prompt,
      cursor: () => store.cursor,
      set: (prompt: ComposerPrompt, cursor = store.cursor) => setStore({ prompt, cursor }),
    },
  }
}

describe("Composer attachment ownership", () => {
  test("keeps an async attachment with the Composer where it started", async () => {
    await new Promise<void>((resolveTest, rejectTest) => {
      createRoot((dispose) => {
        const first = target()
        const second = target()
        const stored = Promise.withResolvers<{ id: string; url: string }>()
        let active = first.capture

        const attachments = createComposerAttachments({
          capture: () => active,
          editor: () => document.createElement("div"),
          focusEditor() {},
          addPart: () => false,
          setDraggingType() {},
          directory: () => "C:/repo",
          destination: () => ({
            input: { image: true, pdf: true },
            local: false,
            upload: () => Promise.reject(new Error("native attachments must not upload")),
          }),
          isDialogActive: () => false,
          duplicate() {},
          onError: rejectTest,
          onUploadError: rejectTest,
          store: () => stored.promise,
        })

        const pending = attachments.addAttachments([new File(["image"], "image.png", { type: "image/png" })])
        active = second.capture
        stored.resolve({ id: "blob-1", url: "blob:test" })
        void pending.then(() => {
          expect(first.prompt.prompt.some((part) => part.type === "image" && part.blob.id === "blob-1")).toBe(true)
          expect(second.prompt.prompt.some((part) => part.type === "image")).toBe(false)
          dispose()
          resolveTest()
        }, rejectTest)
      })
    })
  })
})

import { expect, test } from "bun:test"
import { render } from "solid-js/web"
import { createComposerAttachments } from "@/composer/attachments/attachments"

test("clears drag state on platform cancellation", async () => {
  let cancel = () => {}

  let subscribed = false
  let dragging: "image" | "@mention" | null = "image"

  const dispose = render(() => {
    createComposerAttachments({
      capture: () => ({ current: () => [], cursor: () => 0, set: () => {} }),
      editor: () => undefined,
      focusEditor: () => {},
      addPart: () => false,
      setDraggingType: (type) => (dragging = type),
      directory: () => "",
      isDialogActive: () => false,
      warn: () => {},
      duplicate: () => {},
      onError: () => {},
      onDragCancel: (callback) => {
        cancel = callback
        subscribed = true

        return () => (subscribed = false)
      },
    })

    return null
  }, document.createElement("div"))

  await Promise.resolve()

  cancel()

  expect(dragging).toBeNull()
  dispose()
  expect(subscribed).toBeFalse()
})

import { expect, test } from "bun:test"
import { createRoot } from "solid-js"
import type { Bridge, BridgeMessage, Installed } from "@opencode/gui-extensions/sdk/bridge"
import { createInstalled } from "../src/runtime/extension/installed"

test("a list main pushes while the initial list is pending wins over the older reply", async () => {
  const listeners = new Set<(message: BridgeMessage) => void>()
  const reply = Promise.withResolvers<readonly Installed[]>()

  const bridge: Bridge = {
    packaged: false,
    call: () => Promise.reject(new Error("no calls in this test")),
    subscribe: async () => ({ available: false }),
    on: (listener) => {
      listeners.add(listener)

      return () => {
        listeners.delete(listener)
      }
    },
    embed: () => {},
    capture: async () => undefined,
    runMenubarItem: () => {},
    configure: () => {},
    manager: {
      list: () => reply.promise,
      enable: async () => {},
      disable: async () => {},
      reload: async () => {},
      install: async () => {},
      remove: async () => {},
      source: async () => "",
      asset: () => "",
    },
  }

  const extension = { id: "fixture", name: "Fixture", version: "1.0.0", builtin: true }
  const root = createRoot((dispose) => ({ installed: createInstalled(bridge), dispose }))
  // Another window disabled the extension before this window's initial list arrived.
  listeners.forEach((listener) => listener({ type: "extensions", list: [{ ...extension, enabled: false }] }))
  reply.resolve([{ ...extension, enabled: true }])
  await Bun.sleep(0)
  expect({ known: root.installed.enableState() !== undefined, enabled: root.installed.list().map((item) => item.enabled) }).toEqual({
    known: true,
    enabled: [false],
  })
  root.dispose()
})

import { afterAll, describe, expect, test } from "bun:test"
import { auth, refreshAuthorization } from "@modelcontextprotocol/client"
import { ConfigMCP } from "@opencode/schema/config/mcp"
import { Credential } from "@opencode/core/credential"
import { Integration } from "@opencode/core/integration"
import { McpClient } from "@opencode/core/mcp/client"
import { McpOAuth } from "@opencode/core/mcp/oauth"
import { Cause, Effect, Exit } from "effect"
import { hostEnvironmentLayer } from "./fixture/environment"

const authServer = Bun.serve({ port: 0, fetch: () => new Response(null, { status: 404 }) })
afterAll(() => authServer.stop(true))

const integrationID = Integration.ID.make("mcp_test")
const methodID = Integration.MethodID.make("oauth")

const remote = (url: string) => new ConfigMCP.Remote({ type: "remote", url, oauth: { client_id: "client" } })

const credential = (input: { access: string; refresh: string; expires?: number; url: string }) =>
  new Credential.Info({
    id: Credential.ID.make("cred_test"),
    integrationID,
    label: "test",
    value: {
      type: "oauth",
      methodID,
      access: input.access,
      refresh: input.refresh,
      expires: input.expires ?? Date.now() - 1000,
      metadata: { serverUrl: input.url, tokenType: "Bearer" },
    },
  })

// Connect-time providers read and write the credential store; this one lives in memory so tests can
// inspect the row the provider leaves behind.
const memoryCredentials = (initial: Credential.Info[]) => {
  const rows = new Map(initial.map((row) => [row.id, row]))
  const unused = () => Effect.die("unused credential method")
  const service = Credential.Service.of({
    all: unused,
    create: unused,
    activate: unused,
    list: (id) => Effect.sync(() => Array.from(rows.values()).filter((row) => row.integrationID === id)),
    get: (id) => Effect.sync(() => rows.get(id)),
    update: (id, updates) =>
      Effect.sync(() => {
        const row = rows.get(id)
        if (row) rows.set(id, new Credential.Info({ ...row, ...updates }))
      }),
    remove: (id) => Effect.sync(() => void rows.delete(id)),
  })
  return { rows, service }
}

const connectProvider = (config: typeof ConfigMCP.Remote.Type, store: ReturnType<typeof memoryCredentials>) =>
  Effect.runPromise(
    McpOAuth.connectProvider({ config, integrationID }).pipe(Effect.provideService(Credential.Service, store.service)),
  )

// Serves authorization server metadata with the given capabilities and records DCR + token requests.
const authorizationServer = (metadata: Record<string, unknown>) => {
  const registrations: unknown[] = []
  const tokenRequests: URLSearchParams[] = []
  const server = Bun.serve({
    port: 0,
    async fetch(request) {
      const url = new URL(request.url)
      if (url.pathname === "/.well-known/oauth-authorization-server")
        return Response.json({
          issuer: url.origin,
          authorization_endpoint: `${url.origin}/authorize`,
          token_endpoint: `${url.origin}/token`,
          registration_endpoint: `${url.origin}/register`,
          response_types_supported: ["code"],
          ...metadata,
        })
      if (request.method === "POST" && url.pathname === "/register") {
        registrations.push(await request.json())
        return Response.json({ client_id: "registered", redirect_uris: [] })
      }
      if (request.method === "POST" && url.pathname === "/token") {
        tokenRequests.push(new URLSearchParams(await request.text()))
        return Response.json({ access_token: "access", token_type: "Bearer" })
      }
      return new Response(null, { status: 404 })
    },
  })
  return { server, registrations, tokenRequests }
}

const start = (
  target: string | ReturnType<typeof Bun.serve>,
  oauth?: ConfigMCP.OAuth,
  store: ReturnType<typeof memoryCredentials> = memoryCredentials([]),
) =>
  Effect.gen(function* () {
    const authorization = yield* McpOAuth.authorize({
      name: "test",
      config: new ConfigMCP.Remote({
        type: "remote",
        url: typeof target === "string" ? target : target.url.href,
        ...(oauth ? { oauth } : {}),
      }),
      integrationID,
      methodID,
    })
    return { authorization, url: new URL(authorization.url) }
  }).pipe(Effect.provideService(Credential.Service, store.service))

const authorize = (redirect_uri?: string) =>
  Effect.runPromise(
    Effect.scoped(
      start(authServer, { client_id: "client", ...(redirect_uri ? { redirect_uri } : {}) }).pipe(
        Effect.map(({ url }) => url.searchParams.get("redirect_uri")),
      ),
    ),
  )

describe("MCP OAuth", () => {
  test("completes interactive authorization through the loopback callback", async () => {
    const tokenRequests: URLSearchParams[] = []
    const server = Bun.serve({
      port: 0,
      async fetch(request) {
        const url = new URL(request.url)
        if (request.method !== "POST" || url.pathname !== "/token") return new Response(null, { status: 404 })
        tokenRequests.push(new URLSearchParams(await request.text()))
        return Response.json({
          access_token: "access",
          token_type: "Bearer",
          refresh_token: "refresh",
          expires_in: 3600,
        })
      },
    })

    const credential = await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const { authorization, url: authorizationUrl } = yield* start(server, { client_id: "client" })
          const redirectValue = authorizationUrl.searchParams.get("redirect_uri")
          const state = authorizationUrl.searchParams.get("state")
          if (!redirectValue || !state) throw new Error("Missing OAuth redirect parameters")
          const redirect = new URL(redirectValue)
          redirect.searchParams.set("code", "accepted")
          redirect.searchParams.set("state", state)
          expect((yield* Effect.promise(() => fetch(redirect))).status).toBe(200)
          expect((yield* Effect.promise(() => fetch(redirect))).status).toBe(409)
          return yield* authorization.callback
        }),
      ),
    ).finally(() => server.stop(true))

    expect(credential.access).toBe("access")
    expect(credential.refresh).toBe("refresh")
    expect(tokenRequests).toHaveLength(1)
    expect(tokenRequests[0]?.get("grant_type")).toBe("authorization_code")
    expect(tokenRequests[0]?.get("code")).toBe("accepted")
    expect(tokenRequests[0]?.get("code_verifier")).not.toBeNull()
    expect(tokenRequests[0]?.get("resource")).toBe(server.url.href)
  })

  test("reports a rejected token exchange on the callback page", async () => {
    const server = Bun.serve({
      port: 0,
      fetch(request) {
        if (request.method !== "POST" || new URL(request.url).pathname !== "/token")
          return new Response(null, { status: 404 })
        return Response.json(
          { error: "invalid_client", error_description: "bad_client_secret" },
          { status: 400 },
        )
      },
    })

    const result = await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const { authorization, url: authorizationUrl } = yield* start(server, { client_id: "client" })
          const redirect = new URL(authorizationUrl.searchParams.get("redirect_uri") ?? "")
          redirect.searchParams.set("code", "accepted")
          redirect.searchParams.set("state", authorizationUrl.searchParams.get("state") ?? "")
          const response = yield* Effect.promise(() => fetch(redirect))
          const page = yield* Effect.promise(() => response.text())
          const exit = yield* Effect.exit(authorization.callback)
          return { status: response.status, page, exit }
        }),
      ),
    ).finally(() => server.stop(true))

    expect(result.status).toBe(400)
    expect(result.page).toContain("Authorization failed")
    expect(result.page).toContain("bad_client_secret")
    expect(result.exit._tag).toBe("Failure")
  })

  test("refreshes tokens loaded from a persisted credential", async () => {
    const tokenRequests: URLSearchParams[] = []
    const server = Bun.serve({
      port: 0,
      async fetch(request) {
        const url = new URL(request.url)
        if (request.method !== "POST" || url.pathname !== "/token") return new Response(null, { status: 404 })
        tokenRequests.push(new URLSearchParams(await request.text()))
        return Response.json({ access_token: "next", token_type: "Bearer" })
      },
    })
    const store = memoryCredentials([credential({ access: "expired", refresh: "refresh", url: server.url.href })])
    const oauthProvider = await connectProvider(remote(server.url.href), store)

    const result = await auth(oauthProvider, { serverUrl: server.url.href }).finally(() => server.stop(true))

    expect(result).toBe("AUTHORIZED")
    expect(tokenRequests).toHaveLength(1)
    expect(tokenRequests[0]?.get("grant_type")).toBe("refresh_token")
    expect(tokenRequests[0]?.get("refresh_token")).toBe("refresh")
    // The refreshed tokens land on the same credential row, stamped with the issuer they were minted by.
    const stored = store.rows.get(Credential.ID.make("cred_test"))?.value
    expect(stored?.type === "oauth" && stored.access).toBe("next")
    expect(stored?.type === "oauth" && stored.metadata?.issuer).toBe(server.url.href)
  })

  test("reports needs_auth for an unauthorized server without registering a client", async () => {
    let registrations = 0
    const server = Bun.serve({
      port: 0,
      fetch(request) {
        const url = new URL(request.url)
        if (request.method === "POST" && url.pathname === "/register") registrations++
        if (url.pathname === "/mcp") return new Response(null, { status: 401 })
        return new Response(null, { status: 404 })
      },
    })
    const config = new ConfigMCP.Remote({ type: "remote", url: `${server.url.origin}/mcp` })
    const oauthProvider = await connectProvider(config, memoryCredentials([]))

    const exit = await Effect.runPromise(
      Effect.scoped(McpClient.connect("test", config, import.meta.dir, oauthProvider)).pipe(
        Effect.provide(hostEnvironmentLayer),
        Effect.exit,
      ),
    ).finally(() => server.stop(true))

    const error = Exit.isFailure(exit) && Cause.squash(exit.cause)
    expect(error).toBeInstanceOf(McpClient.NeedsAuthError)
    expect(error instanceof McpClient.NeedsAuthError && error.message).toBe(
      `MCP server "${config.url}" requires a login before it can register a client`,
    )
    expect(registrations).toBe(0)
  })

  test("drops an invalidated credential only while it still holds the presented token", async () => {
    const url = authServer.url.href
    const rotated = memoryCredentials([credential({ access: "a", refresh: "r1", url })])
    const rotatedProvider = await connectProvider(remote(url), rotated)
    await rotatedProvider.tokens()
    // Another connection refreshed first; the row now holds a token this provider never presented.
    await Effect.runPromise(
      rotated.service.update(Credential.ID.make("cred_test"), {
        value: credential({ access: "b", refresh: "r2", url }).value,
      }),
    )
    await rotatedProvider.invalidateCredentials?.("tokens")
    expect(rotated.rows.size).toBe(1)

    const stale = memoryCredentials([credential({ access: "a", refresh: "r1", url })])
    const staleProvider = await connectProvider(remote(url), stale)
    await staleProvider.tokens()
    await staleProvider.invalidateCredentials?.("tokens")
    expect(stale.rows.size).toBe(0)
  })

  test("shares concurrent refreshes for the same token", async () => {
    let requests = 0
    const pending = Promise.withResolvers<void>()
    const server = Bun.serve({
      port: 0,
      async fetch(request) {
        const body = new URLSearchParams(await request.text())
        if (body.get("grant_type") !== "refresh_token") return new Response(null, { status: 404 })
        requests++
        await pending.promise
        return Response.json({ access_token: "access", token_type: "Bearer", refresh_token: "next" })
      },
    })
    const fetchFn = await Effect.runPromise(McpOAuth.loggedFetch({ server: "test" }))
    const options = {
      metadata: {
        issuer: server.url.origin,
        authorization_endpoint: `${server.url.origin}/authorize`,
        token_endpoint: `${server.url.origin}/token`,
        response_types_supported: ["code"],
      },
      clientInformation: { client_id: "client" },
      refreshToken: "refresh",
      fetchFn,
    }

    const first = refreshAuthorization(new URL(server.url.origin), options)
    const second = refreshAuthorization(new URL(server.url.origin), options)
    // Both refreshes must reach the token endpoint before the shared response is released.
    await new Promise((resolve) => setTimeout(resolve, 50))

    expect(requests).toBe(1)
    pending.resolve()
    const results = await Promise.all([first, second]).finally(() => server.stop(true))
    expect(results).toEqual([
      { access_token: "access", token_type: "Bearer", refresh_token: "next" },
      { access_token: "access", token_type: "Bearer", refresh_token: "next" },
    ])
  })

  test("generates a loopback redirect URL when none is configured", async () => {
    expect(await authorize()).toMatch(/^http:\/\/127\.0\.0\.1:\d+\/callback$/)
  })

  test("preserves a configured redirect URL and fixed port", async () => {
    const reservation = Bun.serve({ port: 0, fetch: () => new Response() })
    const redirect = `http://127.0.0.1:${reservation.port}/fixed-callback`
    reservation.stop(true)

    expect(await authorize(redirect)).toBe(redirect)
  })

  test("rejects an invalid redirect URL", async () => {
    await expect(authorize("not a URL")).rejects.toThrow(TypeError)
  })

  test("rejects an authorization endpoint that is not http or https", async () => {
    const { server } = authorizationServer({ authorization_endpoint: "file:///tmp/authorize" })

    await expect(Effect.runPromise(Effect.scoped(start(server))).finally(() => server.stop(true))).rejects.toThrow(
      "returned a file: authorization URL",
    )
  })

  test("sends the configured URL as the resource when the server publishes no metadata", async () => {
    const { server, tokenRequests } = authorizationServer({})
    const url = `${server.url.origin}/mcp`
    const oauthProvider = await connectProvider(
      remote(url),
      memoryCredentials([credential({ access: "expired", refresh: "refresh", url })]),
    )

    await auth(oauthProvider, { serverUrl: url }).finally(() => server.stop(true))

    expect(tokenRequests[0]?.get("resource")).toBe(url)
  })

  test("discovers resource metadata without the query the transport dialed", async () => {
    const probes: string[] = []
    const server = Bun.serve({
      port: 0,
      fetch(request) {
        probes.push(new URL(request.url).pathname + new URL(request.url).search)
        return new Response(null, { status: 404 })
      },
    })
    const url = `${server.url.origin}/mcp`
    const oauthProvider = await connectProvider(remote(url), memoryCredentials([]))

    await auth(oauthProvider, { serverUrl: `${url}?codemode=false` })
      .catch(() => undefined)
      .finally(() => server.stop(true))

    expect(probes).toContain("/.well-known/oauth-protected-resource/mcp")
    expect(probes.some((probe) => probe.includes("codemode"))).toBe(false)
  })

  test("keeps the configured URL as the resource when metadata echoes the dialed query", async () => {
    const tokenRequests: URLSearchParams[] = []
    const server = Bun.serve({
      port: 0,
      async fetch(request) {
        const url = new URL(request.url)
        if (url.pathname === "/.well-known/oauth-authorization-server")
          return Response.json({
            issuer: url.origin,
            authorization_endpoint: `${url.origin}/authorize`,
            token_endpoint: `${url.origin}/token`,
            response_types_supported: ["code"],
          })
        if (url.pathname === "/.well-known/oauth-protected-resource/mcp")
          return Response.json({ resource: `${url.origin}/mcp${url.search}`, authorization_servers: [url.origin] })
        if (request.method === "POST" && url.pathname === "/token") {
          tokenRequests.push(new URLSearchParams(await request.text()))
          return Response.json({ access_token: "next", token_type: "Bearer" })
        }
        return new Response(null, { status: 404 })
      },
    })
    const url = `${server.url.origin}/mcp`
    const oauthProvider = await connectProvider(
      remote(url),
      memoryCredentials([credential({ access: "expired", refresh: "refresh", url })]),
    )

    // The transport dials with ?codemode=false and follows the 401 challenge to metadata that echoes it.
    await auth(oauthProvider, {
      serverUrl: `${url}?codemode=false`,
      resourceMetadataUrl: new URL(`${server.url.origin}/.well-known/oauth-protected-resource/mcp?codemode=false`),
    }).finally(() => server.stop(true))

    expect(tokenRequests[0]?.get("grant_type")).toBe("refresh_token")
    expect(tokenRequests[0]?.get("resource")).toBe(url)
  })

  test("finds resource metadata through the 401 header when the well-known path is not served", async () => {
    const server = Bun.serve({
      port: 0,
      fetch(request) {
        const url = new URL(request.url)
        if (url.pathname === "/mcp")
          return new Response(null, {
            status: 401,
            headers: { "WWW-Authenticate": `Bearer resource_metadata="${url.origin}/custom/metadata"` },
          })
        if (url.pathname === "/custom/metadata")
          return Response.json({ resource: `${url.origin}/mcp`, authorization_servers: [`${url.origin}/as`] })
        if (url.pathname === "/.well-known/oauth-authorization-server/as")
          return Response.json({
            issuer: `${url.origin}/as`,
            authorization_endpoint: `${url.origin}/as/authorize`,
            token_endpoint: `${url.origin}/as/token`,
            response_types_supported: ["code"],
          })
        return new Response(null, { status: 404 })
      },
    })
    const { url } = await Effect.runPromise(
      Effect.scoped(start(`${server.url.origin}/mcp`, { client_id: "client" })),
    ).finally(() => server.stop(true))
    expect(url.pathname).toBe("/as/authorize")
  })

  test("uses configured authorization server metadata when the resource publishes none", async () => {
    const { server: issuer } = authorizationServer({})
    const resource = Bun.serve({ port: 0, fetch: () => new Response(null, { status: 404 }) })
    const url = `${resource.url.origin}/mcp`
    const oauth = {
      client_id: "client",
      auth_server_metadata_url: `${issuer.url.origin}/.well-known/oauth-authorization-server`,
    }

    const { url: authorization } = await Effect.runPromise(Effect.scoped(start(url, oauth)))
    expect(authorization.origin).toBe(issuer.url.origin)
    expect(authorization.pathname).toBe("/authorize")
    expect(authorization.searchParams.get("resource")).toBe(url)

    const { server, tokenRequests } = authorizationServer({})
    const store = memoryCredentials([credential({ access: "expired", refresh: "refresh", url })])
    const oauthProvider = await connectProvider(
      new ConfigMCP.Remote({
        type: "remote",
        url,
        oauth: { ...oauth, auth_server_metadata_url: `${server.url.origin}/.well-known/oauth-authorization-server` },
      }),
      store,
    )
    await auth(oauthProvider, { serverUrl: url }).finally(() => {
      resource.stop(true)
      issuer.stop(true)
      server.stop(true)
    })
    expect(tokenRequests[0]?.get("grant_type")).toBe("refresh_token")
  })

  test("requests offline_access without forcing a consent prompt", async () => {
    const { server } = authorizationServer({ scopes_supported: ["read", "offline_access"] })
    const { url } = await Effect.runPromise(
      Effect.scoped(start(server, { client_id: "client", scope: "read" })),
    ).finally(() => server.stop(true))
    expect(url.searchParams.get("scope")).toBe("read offline_access")
    expect(url.searchParams.has("prompt")).toBe(false)
  })

  test("forwards iss from the redirect so issuer-advertising servers can complete", async () => {
    const { server } = authorizationServer({ authorization_response_iss_parameter_supported: true })
    const result = await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const { authorization, url } = yield* start(server)
          const redirect = new URL(url.searchParams.get("redirect_uri")!)
          redirect.searchParams.set("code", "accepted")
          redirect.searchParams.set("state", url.searchParams.get("state")!)
          redirect.searchParams.set("iss", server.url.origin)
          yield* Effect.promise(() => fetch(redirect))
          return yield* authorization.callback
        }),
      ),
    ).finally(() => server.stop(true))
    expect(result.access).toBe("access")
  })

  describe("client registration", () => {
    const cimd = { client_id_metadata_document_supported: true, token_endpoint_auth_methods_supported: ["none"] }

    test("uses the client metadata document when the server supports public CIMD clients", async () => {
      const { server, registrations, tokenRequests } = authorizationServer(cimd)
      const credential = await Effect.runPromise(
        Effect.scoped(
          Effect.gen(function* () {
            const { authorization, url } = yield* start(server)
            expect(url.searchParams.get("client_id")).toBe(McpOAuth.CLIENT_METADATA_URL)
            const redirect = new URL(url.searchParams.get("redirect_uri")!)
            redirect.searchParams.set("code", "accepted")
            redirect.searchParams.set("state", url.searchParams.get("state")!)
            yield* Effect.promise(() => fetch(redirect))
            return yield* authorization.callback
          }),
        ),
      ).finally(() => server.stop(true))

      expect(registrations).toHaveLength(0)
      expect(tokenRequests[0]?.get("client_id")).toBe(McpOAuth.CLIENT_METADATA_URL)
      expect(McpOAuth.clientFromCredential(credential)).toEqual({
        client_id: McpOAuth.CLIENT_METADATA_URL,
        issuer: server.url.origin,
      })
    })

    test("registers dynamically when the server does not accept public clients", async () => {
      const { server, registrations } = authorizationServer({
        client_id_metadata_document_supported: true,
        token_endpoint_auth_methods_supported: ["client_secret_post"],
      })
      const { url } = await Effect.runPromise(Effect.scoped(start(server))).finally(() => server.stop(true))
      expect(url.searchParams.get("client_id")).toBe("registered")
      expect(registrations).toHaveLength(1)
    })

    test("reuses the client registered by an earlier login", async () => {
      const { server, registrations } = authorizationServer({})
      const previous = credential({ access: "a", refresh: "r", url: server.url.href })
      const client = { client_id: "registered", issuer: server.url.origin }
      const store = memoryCredentials([
        new Credential.Info({ ...previous, value: { ...previous.value, metadata: { client } } }),
      ])
      const { url } = await Effect.runPromise(Effect.scoped(start(server, undefined, store))).finally(() =>
        server.stop(true),
      )
      expect(url.searchParams.get("client_id")).toBe("registered")
      expect(registrations).toHaveLength(0)
    })

    test("registers dynamically when a custom redirect_uri is configured", async () => {
      const { server, registrations } = authorizationServer(cimd)
      const { url } = await Effect.runPromise(
        Effect.scoped(start(server, { redirect_uri: "http://127.0.0.1:0/custom" })),
      ).finally(() => server.stop(true))
      expect(url.searchParams.get("client_id")).toBe("registered")
      expect(registrations).toHaveLength(1)
    })
  })
})

import { expect, test } from "bun:test"
import path from "node:path"
import type { IntegrationInfo, McpServer } from "@opencode/client"
import { mcpAuthChoices } from "../src/commands/handlers/mcp/auth"

const server = (
  name: string,
  integrationID?: string,
  status: McpServer["status"] = { status: "pending" },
): McpServer => ({ name, integrationID, status })

const integration = (id: string, methods: IntegrationInfo["methods"], connected = false): IntegrationInfo => ({
  id,
  name: id,
  methods,
  connections: connected ? [{ type: "credential", method: "oauth", id: "cred_1", label: "Work" }] : [],
})

test("offers only OAuth-capable MCP servers by their server identity", () => {
  expect(
    mcpAuthChoices(
      [
        server("Linear", "mcp_linear", { status: "needs_auth", error: "expired" }),
        server("Local"),
        server("API key only", "mcp_key"),
        server("GitHub", "mcp_github"),
        server("Sentry", "mcp_sentry", { status: "failed", error: "boom" }),
        server("Unresolved", "mcp_missing"),
      ],
      [
        integration("mcp_linear", [{ type: "oauth", id: "login", label: "Linear" }], true),
        integration("mcp_github", [{ type: "oauth", id: "login", label: "GitHub" }]),
        integration("mcp_sentry", [{ type: "oauth", id: "login", label: "Sentry" }]),
        integration("mcp_key", [{ type: "key" }]),
        integration("Linear", [{ type: "oauth", id: "login", label: "A provider with a colliding name" }]),
      ],
    ),
  ).toEqual([
    { value: "mcp_github", label: "GitHub", category: "MCP", connected: false, hint: undefined },
    { value: "mcp_linear", label: "Linear", category: "MCP", connected: true, hint: "needs authentication" },
    { value: "mcp_sentry", label: "Sentry", category: "MCP", connected: false, hint: "failed" },
  ])
})

test("mcp auth accepts an optional server name and rejects no-name noninteractive calls before connecting", async () => {
  const cli = (args: string[]) =>
    Bun.spawn([process.execPath, "run", "src/index.ts", "mcp", "auth", ...args], {
      cwd: path.join(import.meta.dir, ".."),
      stdout: "pipe",
      stderr: "pipe",
    })
  const help = cli(["--help"])
  expect(await new Response(help.stdout).text()).toContain("opencode mcp auth [flags] [<name>]")
  expect(await help.exited).toBe(0)

  const missing = cli([])
  expect(await new Response(missing.stdout).text()).toContain(
    "Pass an MCP server name when running without an interactive terminal",
  )
  expect(await new Response(missing.stderr).text()).toBe("")
  expect(await missing.exited).toBe(1)
})

import { expect } from "bun:test"
import { Effect, Schema } from "effect"
import { LLM, LLMRequest, Message, ToolDefinition } from "../../src/index.js"
import { LLMClient, Route } from "../../src/route/client.js"
import { Auth } from "../../src/route/auth.js"
import { Endpoint } from "../../src/route/endpoint.js"
import { OpenAIResponses } from "../../src/protocols/openai-responses.js"
import { OpenAI, Azure, XAI, Anthropic, OpenAICompatibleResponses } from "../../src/providers/index.js"
import { testEffect } from "../lib/effect.js"
import { dynamicResponse, fixedResponse } from "../lib/http.js"
import { sseEvents } from "../lib/sse.js"

const checkpoint = { type: "compaction", id: "cmp_1", encrypted_content: "opaque" }
const retained = {
  type: "message",
  role: "user",
  id: "msg_1",
  status: "completed",
  content: [{ type: "input_text", text: "retained" }],
}
const output = [retained, checkpoint]

testEffect(
  dynamicResponse(({ request, text, respond }) =>
    Effect.sync(() => {
      expect(request.headers["x-deployment"]).toBe("fixture")
      expect(request.headers["x-override"]).toBe("request")
      expect(request.headers["x-default"]).toBe("configured")
      expect(request.headers.authorization).toBe("Bearer test")
      expect(new URL(request.url).searchParams.get("api-version")).toBe("fixture")
      expect(new URL(request.url).searchParams.get("trace")).toBe("request")
      if (new URL(request.url).pathname.endsWith("/compact")) {
        expect(JSON.parse(text)).toEqual({
          model: "overlaid",
          input: [{ type: "message", role: "user", content: [{ type: "input_text", text: "hello" }] }],
          instructions: "request instructions",
          previous_response_id: "resp_previous",
        })
        return respond(JSON.stringify({ object: "response.compaction", output }))
      }
      return respond(sseEvents({ type: "response.completed", response: { id: "resp_1" } }))
    }),
  ),
).effect("generation and compaction share deployment headers, defaults, auth, query, and middleware", () =>
  Effect.gen(function* () {
    const headers: string[] = []
    const middleware: string[] = []
    const route = Route.make({
      id: "compaction-headers",
      provider: "openai",
      protocol: OpenAIResponses.protocol,
      compact: OpenAIResponses.route.compact,
      transport: OpenAIResponses.httpTransport,
      endpoint: Endpoint.path(({ body }) => `/${body.model}/responses`, {
        baseURL: "https://example.com",
        query: { "api-version": "fixture" },
      }),
      auth: Auth.bearer("test"),
      headers: ({ request }) => {
        expect(request.providerOptions?.store).toBe(false)
        headers.push(String(request.model.id))
        return { "x-deployment": "fixture", "x-override": "route" }
      },
      defaults: {
        headers: { "x-default": "configured", "x-override": "configured" },
        providerOptions: { store: false },
        http: { body: { instructions: "default instructions" } },
      },
    })
    const request = LLM.request({
      model: route.model({ id: "fixture" }),
      prompt: "hello",
      system: "system instructions",
      http: {
        headers: { "x-override": "request" },
        query: { trace: "request" },
        body: {
          model: "overlaid",
          instructions: "request instructions",
          previous_response_id: "resp_previous",
          store: false,
          stream: true,
        },
      },
    })
    const options: Parameters<typeof LLMClient.compact>[1] = {
      http: (request, next) => {
        middleware.push(new URL(request.url).pathname)
        return next(request)
      },
    }
    yield* LLMClient.generate(request, options)
    yield* LLMClient.compact(request, options)
    expect(headers).toEqual(["fixture", "fixture"])
    expect(middleware).toEqual(["/fixture/responses", "/fixture/responses/compact"])
  }),
)

for (const model of [
