import { expect, test } from "bun:test"
import type { SessionMessageInfo } from "@opencode/client/promise"
import { batch, createMemo, createRoot, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { ServerScope, SessionRouteKey, SessionStateKey } from "../src/runtime/server/scope"
import { createTimelineCache } from "../src/session/timeline/cache"

function setup() {
  return createRoot((dispose) => {
    const [state, setState] = createStore({
      id: "ses_a",
      directory: "/repo",
      visible: true,
      messages: {
        ses_a: [{ id: "msg_a", type: "user", text: "First session", time: { created: 1 } }],
        ses_b: [{ id: "msg_b", type: "user", text: "Second session", time: { created: 2 } }],
      } as Record<string, SessionMessageInfo[]>,
    })

    const views = new Map<
      string,
      { active: () => boolean; messages: () => SessionMessageInfo[]; element: HTMLDivElement }
    >()

    const disposed: string[] = []

    const cache = createTimelineCache(
      {
        identity: {
          params: {
            get id() {
              return state.id
            },
            serverKey: "local",
          },
          sessionID: () => state.id,
          workspaceKey: () => SessionStateKey.from(ServerScope.local, SessionRouteKey.fromRoute(state.directory)),
          sessionKey: () =>
            SessionStateKey.from(ServerScope.local, SessionRouteKey.fromRoute(state.directory, state.id)),
        },
        data: {
          info: createMemo(() => ({
            id: state.id,
            projectID: "project",
            cost: 0,
            tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
            time: { created: 1, updated: 1 },
            location: { directory: state.directory },
          })),
          parent: () => undefined,
          parentID: () => undefined,
          status: () => ({ type: "idle" }),
        },
        history: { messages: () => state.messages[state.id] ?? [] },
      },
      (source, active) => {
        const id = source.identity.sessionID()!
        const element = document.createElement("div")
        createMemo(() =>
          element.setAttribute(
            "data-messages",
            source.history
              .messages()
              .map((message) => message.id)
              .join(","),
          ),
        )
        views.set(id, { active, messages: source.history.messages, element })
        onCleanup(() => disposed.push(id))

        return element
      },
      () => state.visible,
    )

    return { state, setState, cache, views, disposed, dispose }
  })
}

test("reuses a session view and refreshes its own history when selected again", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("id", "ses_b")
    const second = input.cache()
    expect(second).not.toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(false)
    expect(input.views.get("ses_a")!.element.dataset.messages).toBe("msg_a")
    expect(input.views.get("ses_b")!.element.dataset.messages).toBe("msg_b")

    input.setState("messages", "ses_a", [
      { id: "msg_c", type: "user", text: "Updated while inactive", time: { created: 3 } },
    ])
    input.setState("id", "ses_a")
    expect(input.cache()).toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(true)
    expect(input.views.get("ses_a")!.element.dataset.messages).toBe("msg_c")
    expect(input.views.get("ses_b")!.element.dataset.messages).toBe("msg_b")
    expect(input.disposed).toEqual([])
  } finally {
    input.dispose()
  }

  expect(input.disposed.sort()).toEqual(["ses_a", "ses_b"])
})

test("suspends a detached mobile view and reuses it when the conversation returns", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("visible", false)
    expect(input.views.get("ses_a")!.active()).toBe(false)
    input.setState("visible", true)
    expect(input.cache()).toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(true)
  } finally {
    input.dispose()
  }
})

test("disposes views whose Location-scoped providers no longer match", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("directory", "/other")
    expect(input.cache()).not.toBe(first)
    expect(input.disposed).toEqual(["ses_a"])
    input.setState("directory", "/repo")
    expect(input.cache()).not.toBe(first)
    expect(input.disposed).toEqual(["ses_a", "ses_a"])
  } finally {
    input.dispose()
  }

  expect(input.disposed).toHaveLength(3)
})

test("disposes views on workspace changes while the destination is not rendered", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("visible", false)
    input.setState("directory", "/other")
    expect(input.disposed).toEqual(["ses_a"])
    input.setState("directory", "/repo")
    input.setState("visible", true)
    expect(input.cache()).not.toBe(first)
  } finally {
    input.dispose()
  }

  expect(input.disposed).toEqual(["ses_a", "ses_a"])
})

for (const order of ["session-first", "workspace-first"] as const) {
  test(`keeps views live across five workspaces when updates are ${order}`, () => {
    const input = setup()
    const render = createRoot((dispose) => ({ selected: createMemo(input.cache), dispose }))
    const visited = ["ses_a"]

    try {
      ;["ses_b", "ses_c", "ses_d", "ses_e", "ses_a", "ses_c", "ses_b", "ses_e", "ses_d", "ses_a"].forEach(
        (id, index) => {
          batch(() => {
            if (order === "workspace-first") input.setState("directory", `/repo/${id}`)
            input.setState("id", id)

            if (order === "session-first") input.setState("directory", `/repo/${id}`)
          })
          expect(input.disposed).toEqual(visited)
          input.setState("messages", id, [
            { id: `msg_live_${index}`, type: "user", text: "Live update", time: { created: index + 3 } },
          ])
          expect((render.selected() as HTMLDivElement).dataset.messages).toBe(`msg_live_${index}`)
          expect(input.views.get(id)!.active()).toBe(true)
          visited.push(id)
        },
      )
    } finally {
      render.dispose()
      input.dispose()
    }
  })
}

test("evicts the least recently selected view and disposes all retained owners", () => {
  const input = setup()

  try {
    const first = input.cache()
    Array.from({ length: 15 }, (_, index) => `ses_${index}`).forEach((id) => {
      input.setState("id", id)
      input.cache()
    })
    input.setState("id", "ses_a")
    expect(input.cache()).toBe(first)
    input.setState("id", "ses_last")
    input.cache()
    expect(input.disposed).toEqual(["ses_0"])
    input.setState("id", "ses_0")
    input.cache()
    expect(input.disposed).toEqual(["ses_0", "ses_1"])
  } finally {
    input.dispose()
  }

  expect(input.disposed).toHaveLength(18)
})

import { expect, test } from "bun:test"
import { resolveObjectURL } from "node:buffer"
import { createDraftStore, resolveBlobUrl } from "@/runtime/persistence/drafts"

function fixture(id: string, getBlob: () => Promise<Blob | null>) {
  const documents = new Map([
    ["history", JSON.stringify({ entries: [{ prompt: [{ type: "image", blob: { id } }] }] })],
    ["draft", JSON.stringify({ prompt: [{ type: "image", blob: { id } }] })],
  ])

  const store = createDraftStore({
    get: async (key) => documents.get(key) ?? null,
    set: async (key, value) => {
      documents.set(key, value)

      return []
    },
    remove: async (key) => void documents.delete(key),
    putBlob: async () => id,
    getBlob,
  })

  return { store, documents }
}

test("loading history and a draft reads no image bytes", async () => {
  let reads = 0

  const { store } = fixture("history-cache-lazy", async () => {
    reads++

    return new Blob(["shared screenshot"])
  })

  const [history, draft] = await Promise.all([store.getItem("history"), store.getItem("draft")])
  expect(JSON.parse(history!).entries[0].prompt[0].blob).toEqual({ id: "history-cache-lazy" })
  expect(JSON.parse(draft!).prompt[0].blob).toEqual({ id: "history-cache-lazy" })
  expect(reads).toBe(0)
})

test("deduplicates concurrent resolves without invalidating either live reference", async () => {
  const pending = Promise.withResolvers<Blob | null>()
  const started = Promise.withResolvers<void>()
  let reads = 0

  const { store } = fixture("history-cache-concurrent", () => {
    reads++
    started.resolve()

    return pending.promise
  })

  await store.getItem("history")
  const first = resolveBlobUrl({ id: "history-cache-concurrent" })
  const second = resolveBlobUrl({ id: "history-cache-concurrent" })
  await started.promise
  pending.resolve(new Blob(["shared screenshot"]))
  const [a, b] = await Promise.all([first, second])
  expect(a).toBe(b!)
  expect(reads).toBe(1)
  await store.removeItem("history")
  expect(await resolveObjectURL(a!)?.text()).toBe("shared screenshot")
  expect(await resolveBlobUrl({ id: "history-cache-concurrent" })).toBe(a!)
  expect(reads).toBe(1)
})

test("a document re-read while its image is live gets the URL back without a read", async () => {
  let reads = 0

  const { store, documents } = fixture("history-cache-remount", async () => {
    reads++

    return new Blob(["saved screenshot"])
  })

  const url = await resolveBlobUrl({ id: "history-cache-remount" })
  const changed = JSON.parse(documents.get("history")!)
  changed.entries[0].prompt.unshift({ type: "text", content: "new admission" })
  documents.set("history", JSON.stringify(changed))
  const second = JSON.parse((await store.getItem("history"))!)
  expect(second.entries[0].prompt[0].content).toBe("new admission")
  expect(second.entries[0].prompt[1].blob).toEqual({ id: "history-cache-remount", url })
  expect(reads).toBe(1)
})

test("reuses a just-stored attachment without a round trip", async () => {
  let reads = 0

  const { store } = fixture("history-cache-put", async () => {
    reads++

    return new Blob(["unexpected read"])
  })

  const reference = await store.putBlob(new Blob(["pending admission"]))
  expect(JSON.parse((await store.getItem("draft"))!).prompt[0].blob).toEqual(reference)
  expect(await resolveBlobUrl({ id: reference.id })).toBe(reference.url)
  expect(reads).toBe(0)
  expect(await resolveObjectURL(reference.url)?.text()).toBe("pending admission")
})

test("does not retain a missing blob result", async () => {
  let reads = 0
  fixture("history-cache-missing", async () => (++reads === 1 ? null : new Blob(["arrived"])))
  expect(await resolveBlobUrl({ id: "history-cache-missing" })).toBeUndefined()
  expect(await resolveBlobUrl({ id: "history-cache-missing" })).toStartWith("blob:")
  expect(reads).toBe(2)
})

test("retries after a failed blob read", async () => {
  let reads = 0
  fixture("history-cache-failure", async () => {
    if (++reads === 1) throw new Error("temporary storage failure")

    return new Blob(["recovered"])
  })
  await expect(resolveBlobUrl({ id: "history-cache-failure" })).rejects.toThrow("temporary storage failure")
  expect(await resolveBlobUrl({ id: "history-cache-failure" })).toStartWith("blob:")
  expect(reads).toBe(2)
})

test("keeps different blob IDs independent", async () => {
  const reads: string[] = []
  createDraftStore({
    get: async () => null,
    set: async () => [],
    remove: async () => {},
    putBlob: async () => "unused",
    getBlob: async (id) => {
      reads.push(id)

      return new Blob([id])
    },
  })
  const urls = await Promise.all(["history-cache-first", "history-cache-second"].map((id) => resolveBlobUrl({ id })))
  expect(urls[0]).not.toBe(urls[1])
  expect(await Promise.all(urls.map((url) => resolveObjectURL(url!)?.text()))).toEqual(reads)
  expect(reads).toEqual(["history-cache-first", "history-cache-second"])
})

name: deploy

on:
  push:
    branches:
      - dev
      - production
      - beta
  workflow_dispatch:

concurrency: ${{ github.workflow }}-${{ github.ref }}

permissions:
  contents: read
  id-token: write

jobs:
  deploy:
    if: github.repository == 'anomalyco/opencode' && (github.ref_name == 'dev' || github.ref_name == 'production' || github.ref_name == 'beta')
    runs-on: blacksmith-4vcpu-ubuntu-2404
    environment: ${{ github.ref_name }}
    steps:
      - uses: actions/checkout@f43a0e5ff2bd294095638e18286ca9a3d1956744 # v3.6.0

      - uses: ./.github/actions/setup-bun

      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: "24"

      - uses: aws-actions/configure-aws-credentials@7474bc4690e29a8392af63c5b98e7449536d5c3a # v4.3.1
        if: github.ref_name != 'beta'
        with:
          role-to-assume: ${{ vars.AWS_DEPLOY_ROLE_ARN }}
          role-session-name: opencode-${{ github.run_id }}
          aws-region: us-east-1

      - run: bun sst deploy --stage=${{ github.ref_name }}
        env:
          GITHUB_TOKEN: ${{ github.token }}
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          PLANETSCALE_SERVICE_TOKEN_NAME: ${{ secrets.PLANETSCALE_SERVICE_TOKEN_NAME }}
          PLANETSCALE_SERVICE_TOKEN: ${{ secrets.PLANETSCALE_SERVICE_TOKEN }}
          STRIPE_SECRET_KEY: ${{ github.ref_name == 'production' && secrets.STRIPE_SECRET_KEY_PROD || secrets.STRIPE_SECRET_KEY_DEV }}
          SENTRY_AUTH_TOKEN: ${{ secrets.SENTRY_AUTH_TOKEN }}
          SENTRY_ORG: ${{ vars.SENTRY_ORG }}
          SENTRY_PROJECT: ${{ vars.WEB_SENTRY_PROJECT }}
          SENTRY_RELEASE: web@${{ github.sha }}
          VITE_SENTRY_DSN: ${{ vars.WEB_SENTRY_DSN }}
          VITE_SENTRY_RELEASE: web@${{ github.sha }}

import { batch, untrack, type Accessor } from "solid-js"
import type { SetStoreFunction, Store } from "solid-js/store"
import type {
  ComposerAgentPart,
  ComposerFilePart,
  ComposerSkillPart,
  ComposerPersistedState,
  ComposerPrompt,
} from "../types"
import { isAttachment, promptLength } from "../prompt-parts"

export type ComposerStateStore = [
  Store<ComposerPersistedState> | Accessor<Store<ComposerPersistedState>>,
  SetStoreFunction<ComposerPersistedState>,
]

export type ComposerStateStoreInput = ComposerStateStore | Accessor<ComposerStateStore>

export function createComposerEditorActions(input: ComposerStateStoreInput) {
  const tuple = () => (typeof input === "function" ? input() : input)

  const store = () => {
    const value = tuple()[0]

    return typeof value === "function" ? value() : value
  }

  const setStore = () => tuple()[1]

  const clearRetry = () => {
    if (untrack(() => store().retry) !== undefined) setStore()("retry", undefined)
  }

  return {
    get state() {
      return store()
    },
    setPrompt(prompt: ComposerPrompt, cursor?: number) {
      // Persisted setters encode on every call, even inside a reactive batch.
      batch(() => setStore()({ prompt, ...(cursor !== undefined ? { cursor } : {}), retry: undefined }))
    },
    setCursor(cursor: number) {
      if (untrack(() => store().cursor) === cursor) return
      setStore()("cursor", cursor)
    },
    setMode(mode: "normal" | "shell") {
      if (untrack(() => store().mode === mode && store().retry === undefined)) return
      setStore()({ mode, retry: undefined })
    },
    setText(content: string) {
      batch(() =>
        setStore()((state) => ({
          prompt: [
            { type: "text", content, start: 0, end: content.length },
            ...state.prompt.filter(isAttachment),
          ],
          cursor: content.length,
          retry: undefined,
        })),
      )
    },
    addText(content: string) {
      const cursor = store().cursor ?? promptLength(store().prompt)
      batch(() =>
        setStore()((state) => ({
          prompt: insertText(state.prompt, cursor, content),
          cursor: cursor + content.length,
          retry: undefined,
        })),
      )
    },
    removeContext(key: string) {
      setStore()("context", "items", (items) => items.filter((item) => item.key !== key))
      clearRetry()
    },
    addMention(
      mention: ComposerFilePart | ComposerAgentPart | ComposerSkillPart,
      range?: { start: number; end: number },
    ) {
      const text = store()
        .prompt.map((part) => ("content" in part ? part.content : ""))
        .join("")

      const end = range?.end ?? store().cursor ?? text.length
      const start = range?.start ?? text.slice(0, end).lastIndexOf("@")
      setStore()("prompt", insertMention(store().prompt, start < 0 ? end : start, end, mention))
      setStore()("cursor", (start < 0 ? end : start) + mention.content.length + 1)
      clearRetry()
    },
    removeAttachment(id: string) {
      setStore()("prompt", (parts) => parts.filter((part) => !isAttachment(part) || part.id !== id))
      clearRetry()
    },
  }
}

function insertText(prompt: ComposerPrompt, cursor: number, content: string): ComposerPrompt {
  let position = 0
  let inserted = false

  const parts = prompt.flatMap<ComposerPrompt[number]>((part) => {
    if (isAttachment(part)) return [part]
    const start = position
    position += part.content.length

    if (inserted) return [part]

    if (part.type === "text" && cursor >= start && cursor <= position) {
      inserted = true
      const offset = cursor - start

      return [{ ...part, content: part.content.slice(0, offset) + content + part.content.slice(offset) }]
    }

    if (cursor > start) return [part]
    inserted = true

    return [{ type: "text", content, start: 0, end: 0 }, part]
  })

  if (!inserted) parts.push({ type: "text", content, start: 0, end: 0 })

  return withOffsets(parts)
}

function insertMention(
  prompt: ComposerPrompt,
  start: number,
  end: number,
  mention: ComposerFilePart | ComposerAgentPart | ComposerSkillPart,
): ComposerPrompt {
  if (start === 0 && end === 0) {
    return withOffsets([mention, { type: "text", content: " ", start: 0, end: 0 }, ...prompt])
  }

  let position = 0

  const parts = prompt.flatMap<ComposerPrompt[number]>((part) => {
    if (isAttachment(part)) return [part]
    const partStart = position
    position += part.content.length

    if (part.type !== "text" || start < partStart || end > position) return [part]
    const before = part.content.slice(0, start - partStart)
    const after = part.content.slice(end - partStart)

    return [
      ...(before ? [{ type: "text" as const, content: before, start: 0, end: 0 }] : []),
      mention,
      { type: "text" as const, content: ` ${after}`, start: 0, end: 0 },
    ]
  })

  return withOffsets(parts)
}

function withOffsets(prompt: ComposerPrompt): ComposerPrompt {
  let offset = 0

  return prompt.map((part) => {
    if (isAttachment(part)) return part
    const next = { ...part, start: offset, end: offset + part.content.length }
    offset = next.end

    return next
  })
}
